param([string]$BenchmarkRepo="D:\Dev\LotSizingDataModel.Benchmarks",[string]$ModelRepo="D:\Dev\LotSizingDataModel")
Set-StrictMode -Version Latest;$ErrorActionPreference="Stop"
function Ensure([string]$p){if(-not(Test-Path -LiteralPath $p -PathType Container)){New-Item -ItemType Directory -Path $p -Force|Out-Null}}
$g=Join-Path $BenchmarkRepo "catalog\global";$r=Join-Path $BenchmarkRepo "reports\v0.20.0";$d=Join-Path $BenchmarkRepo "docs\benchmarks";Ensure $r;Ensure $d
$base=@(Import-Csv -LiteralPath (Join-Path $g "GLOBAL-NORMALIZED-TRUST-v0.17.0.csv"));$dj=@(Import-Csv -LiteralPath (Join-Path $BenchmarkRepo "benchmarks\DJ2000\metadata\DJ-TRUST-GATE.csv"));$phase1=@($dj|Where-Object{$_.phase-eq"Phase1"-and$_.solution_available-eq"True"-and$_.checker_phase_overall-eq"VALID"})
if($base.Count-ne7888-or$phase1.Count-ne96){throw "Baseline or DJ evidence cardinality failed."};$idx=@{};foreach($x in $phase1){$idx[$x.canonical_id.ToUpperInvariant()]=$x}
$transitions=New-Object System.Collections.Generic.List[object];$out=@($base|ForEach-Object{$id=$_.original_instance_id.ToUpperInvariant();$old=$_.normalized_trust_status;$match=$null;if($_.family-eq"DJ2000"){foreach($key in $idx.Keys){if($id.EndsWith($key,[StringComparison]::OrdinalIgnoreCase)){$match=$idx[$key];break}}};if($null-ne$match){$e=$match;$_.normalized_trust_status="CHECKER_VERIFIED_FEASIBLE";$_.normalization_basis="DJ Phase1 complete solution; full checker campaign 96/96 valid; optimality claim retained but not independently proven";$_.objective_reference=$e.objective;$_.complete_solution_available="True";$_.checker_verified_solution="True";$_.optimality_status="CLAIMED_PROVEN_OPTIMAL_UNVERIFIED";$transitions.Add([pscustomobject]@{global_instance_id=$_.global_instance_id;old_status=$old;new_status=$_.normalized_trust_status;historical_claim=$e.previous_claim;evidence_source="DJ-TRUST-GATE.csv";checker_report=$e.report_directory;decision="PROMOTED_FEASIBILITY_ONLY"})};$_})
$out|Export-Csv -LiteralPath (Join-Path $g "GLOBAL-NORMALIZED-TRUST-v0.20.0.csv") -NoTypeInformation -Encoding UTF8;$out|ConvertTo-Json -Depth 4|Set-Content -LiteralPath (Join-Path $g "GLOBAL-NORMALIZED-TRUST-v0.20.0.json") -Encoding UTF8;$transitions.ToArray()|Export-Csv -LiteralPath (Join-Path $g "GLOBAL-TRUST-TRANSITIONS-v0.20.0.csv") -NoTypeInformation -Encoding UTF8
$phase2=@($dj|Where-Object phase -eq "Phase2");$quarantine=@($phase2|Where-Object{$_.checker_phase_invalid-ne"0"}|ForEach-Object{[pscustomobject]@{family="DJ2000";phase=$_.phase;canonical_id=$_.canonical_id;status="REJECTED_BY_CHECKER";objective=$_.objective;report_directory=$_.report_directory;promotion_allowed="False"}});$quarantine|Export-Csv -LiteralPath (Join-Path $g "GLOBAL-RESULT-QUARANTINE-v0.20.0.csv") -NoTypeInformation -Encoding UTF8
$reports=@(Get-ChildItem -LiteralPath (Join-Path $BenchmarkRepo "benchmarks\DJ2000\checker-reports") -Recurse -File|ForEach-Object{[pscustomobject]@{family="DJ2000";path=$_.FullName;sha256=(Get-FileHash -LiteralPath $_.FullName -Algorithm SHA256).Hash;bytes=$_.Length}});$reports|Export-Csv -LiteralPath (Join-Path $g "GLOBAL-CHECKER-REPORT-MANIFEST-v0.20.0.csv") -NoTypeInformation -Encoding UTF8
@([pscustomobject]@{metric="registry_rows";value=$out.Count},[pscustomobject]@{metric="dj_promotions";value=$transitions.Count},[pscustomobject]@{metric="quarantined";value=$quarantine.Count},[pscustomobject]@{metric="checker_report_files";value=$reports.Count})|Export-Csv -LiteralPath (Join-Path $r "ACCELERATION-SUMMARY-v0.20.0.csv") -NoTypeInformation -Encoding UTF8
$md="# Acceleration pack v0.20.0`r`n`r`nThis release closes roadmap milestone M2 at catalogue level and advances M6. It integrates 96 DJ Phase 1 records already accepted by the full checker campaign and the existing DJ Trust Gate, preserves rejected results in an orthogonal quarantine, and creates a checksum manifest for checker evidence. Canonical XML is unchanged.`r`n";[IO.File]::WriteAllText((Join-Path $d "ACCELERATION-PACK-v0.20.0.md"),$md,(New-Object Text.UTF8Encoding($false)))
Write-Host "ACCELERATION_PACK_V0.20.0";Write-Host("ROWS|"+$out.Count);Write-Host("DJ_PROMOTED|"+$transitions.Count);Write-Host("QUARANTINED|"+$quarantine.Count);Write-Host("CHECKER_REPORTS|"+$reports.Count)
